  str_n7_talk_1 = "\"The Goddess of Victory has forsaken you!\"",
  str_n7_talk_2 = "\"Cursing at you would only be a waste of breath.\"",
  str_n7_talk_3 = "\"Sure, you have a lot of skills, but they're all useless.\"",
  str_n7_talk_4 = "\"When I'm finished with you, you'll never want to look in the mirror again!\"",
  str_n7_talk_5 = "\"Huh? They let fools in here, too?\"",
  str_n7_talk_6 = "\"I suggest you go home and hide under the bed!\"",
  str_n7_talk_7 = "\"Will you have enough time to write your epitaph?\"",
  str_n7_talk_8 = "\"When you fall, the audience will cry, 'Is it over already!?'\"",
  str_n7_talk_9 = "\"For losers, you are indeed strong.\"",
  str_n7_talk_10 = "\"Take one last look at your miserable faces. It'll be the last chance you get.\"",
  str_n7_talk_11 = "\"Losers as pathetic as you are pretty hard to come by.\"",
  str_n7_talk_12 = "\"Losers never fear defeat. That must be why you're not trembling.\"",
  str_n7_talk_13 = "\"The defeated cannot be revived here... Get out of here while you still can!\"",
  str_n7_talk_14 = "\"We're gonna smash you to smithereens!\"",
  str_n7_talk_15 = "\"If you're not afraid of getting hurt, let's get fighting already!\"",
  str_n7_talk_1_1 = "A good offense is the best defense.",
  str_n7_talk_1_2 = "The harder you train, the more you'll win.",
