  str_n7_talk_1_8 = "No foe is more formidable than life.",
  str_n7_talk_1_9 = "Believe in yourself and you'll win.",
  str_n7_talk_1_10 = "Compared to life, match is very easy.",
  str_n7_talk_1_11 = "It's wise to feel fear.",
  str_n7_talk_1_12 = "Don't follow in other's footsteps, make your own.",
  str_n7_talk_1_13 = "Failure will not come close to me.",
  str_n7_talk_1_14 = "All who are willing to compete are valiant, whether they stand or fall.",
